on">เหตุผลการโอน <span class="text-danger">*</span></label><textarea class="form-control" id="transfer-reason" name="reason" maxlength="500" rows="3" required placeholder="เช่น พนักงานลาออก มีผลวันที่..."></textarea><div class="invalid-feedback" data-error-for="reason"></div></div></div><div class="d-flex flex-column-reverse flex-sm-row justify-content-end gap-2 mt-3"><button class="btn btn-app-soft" id="preview-transfer" type="button"><i class="bx bx-search me-1" aria-hidden="true"></i>ตรวจสอบผลกระทบ</button><button class="btn btn-app-primary" id="submit-transfer" type="submit" disabled><i class="bx bx-transfer-alt me-1" aria-hidden="true"></i>โอนเจ้าของและงาน</button></div></div></div>
