<script>$(function(){const form=$('#ownership-transfer-form'),source=$('#transfer-source'),target=$('#transfer-target'),scope=$('#transfer-scope'),teamField=$('#team-field'),customersField=$('#customers-field'),customers=$('#transfer-customers'),preview=$('#transfer-preview'),submit=$('#submit-transfer'),userUrl=@json(route('crm.ownership-transfers.user-options')),customerUrl=@json(route('crm.ownership-transfers.customer-options'));function userSelect(element,activeOnly){window.erpInitSelect2(element,{theme:'bootstrap-5',placeholder:'ค้นหารหัสหรือชื่อพนักงาน',ajax:{url:userUrl,dataType:'json',delay:250,data:p=>({q:p.term||'',page:p.page||1,active_only:activeOnly?1:0}),processResults:d=>d}});}userSelect(source,false);userSelect(target,true);window.erpInitSelect2(customers,{theme:'bootstrap-5',placeholder:'ค้นหารหัสหรือชื่อลูกค้า',maximumSelectionLength:100,ajax:{url:customerUrl,dataType:'json',delay:250,data:p=>({q:p.term||'',page:p.page||1,source_user_id:source.val()}),processResults:d=>d}});function scopeFields(){teamField.toggleClass('d-none',scope.val()!=='TEAM');customersField.toggleClass('d-none',scope.val()!=='SELECTED');}function dirty(){preview.addClass('d-none');submit.prop('disabled',true);}scope.on('change',function(){scopeFields();dirty();});form.on('change input','select,textarea',dirty);scopeFields();$('#preview-transfer').on('click',function(){const button=$(this);button.prop('disabled',true);form.find('.is-invalid').removeClass('is-invalid');form.find('.invalid-feedback').text('');$.post(@json(route('crm.ownership-transfers.preview')),form.serialize()).done(function(data){Object.entries(data.counts).forEach(([key,value])=>preview.find('[data-count="'+key+'"]').text(Number(value).toLocaleString('th-TH')));$('#preview-customers').html(data.customers.length?'<div class="small text-secondary mb-1">ตัวอย่างลูกค้าที่ได้รับผลกระทบ</div>'+data.customers.map(row=>$('<div>').text(row.code+' · '+row.name).html()).join('<br>'):'<div class="text-secondary text-center">ไม่พบงานที่ต้องโอน</div>');preview.removeClass('d-none');submit.prop('disabled',Object.values(data.counts).every(value=>Number(value)===0));}).fail(showErrors).always(()=>button.prop('disabled',false));});function showErrors(xhr){const errors=xhr.responseJSON?.errors;if(errors){Object.entries(errors).forEach(([field,messages])=>{const base=field.split('.')[0],input=form.find('[name="'+base+'"],[name="'+base+'[]"]');input.addClass('is-invalid');form.find('[data-error-for="'+base+'"]').text(messages[0]);});return;}window.erpAjaxError(xhr);}form.on('submit',function(event){event.preventDefault();Swal.fire({icon:'warning',title:'โอนเจ้าของและงาน?',text:'Opportunity และ Activity ที่ยังเปิดจะเปลี่ยนผู้รับผิดชอบทันที',showCancelButton:true,confirmButtonText:'โอนเจ้าของและงาน',cancelButtonText:'ยกเลิก'}).then(result=>{if(!result.isConfirmed)return;submit.prop('disabled',true);$.post(form.attr('action'),form.serialize()).done(response=>Swal.fire({icon:'success',title:response.msg,confirmButtonText:'ตกลง'}).then(()=>location.reload())).fail(xhr=>{submit.prop('disabled',false);showErrors(xhr);});});});});</script>
@endpush
